$id=trim((string)($_SESSION['ALUMNI_MEMBER']??''));if($id===''){header('location:alumni-community.php');exit();}$stmt=mysqli_prepare($con,"SELECT * FROM tblalumni WHERE alumniid=? AND status='active' LIMIT 1");mysqli_stmt_bind_param($stmt,'s',$id);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);$member=$result?mysqli_fetch_assoc($result):null;mysqli_stmt_close($stmt);if(!$member){header('location:alumni-community.php');exit();}if(empty($_SESSION['alumni_concern_csrf']))$_SESSION['alumni_concern_csrf']=bin2hex(random_bytes(32));$message='';$tone='';
if(isset($_POST['submit_concern'])){if(!hash_equals($_SESSION['alumni_concern_csrf'],(string)($_POST['csrf']??''))){$message='Your form expired. Please try again.';$tone='error';}else{$category=trim((string)($_POST['category']??'General feedback'));$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['messagebody']??''));if($subject===''||$body===''){$message='Please add a subject and your concern.';$tone='error';}else{$stmt=mysqli_prepare($con,'INSERT INTO tblalumniconcern(alumniid,category,subject,messagebody) VALUES(?,?,?,?)');mysqli_stmt_bind_param($stmt,'ssss',$member['alumniid'],$category,$subject,$body);if(mysqli_stmt_execute($stmt)){logExternalSystemChange($con,$member['fullname'],'Alumni','ALUMNI_CONCERN_SUBMITTED','Private Alumni concern: '.$subject,$member['alumniid']);$message='Your concern has been sent privately to AYISEC Alumni administration.';$tone='success';$_SESSION['alumni_concern_csrf']=bin2hex(random_bytes(32));}else{$message='Your concern could not be sent. Please try again.';$tone='error';}mysqli_stmt_close($stmt);}}}
