?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Share a concern | AYISEC Alumni</title><link rel="icon" type="image/png" href="logo/logo-transparent.png"><style>:root{--n:#102b4b;--t:#08766f;--p:#f4f7fb;--l:#dce5ed}*{box-sizing:border-box}body{margin:0;background:var(--p);color:#1e293b;font:15px Arial,sans-serif}.wrap{max-width:860px;margin:auto;padding:38px 18px 65px}.hero{background:linear-gradient(120deg,var(--n),var(--t));color:#fff;border-radius:20px;padding:31px}.hero h1,h2{font-family:Georgia,serif}.hero h1{margin:6px 0;font-size:31px}.hero p{margin:0;color:#dcecf0;line-height:1.55}.card{background:#fff;border:1px solid var(--l);border-radius:16px;padding:24px;margin-top:20px}.card h2{color:var(--n);margin:0 0 8px}.note{color:#64748b;line-height:1.55}label{display:block;font-size:12px;font-weight:bold;color:#475569;margin-top:14px}input,select,textarea{width:100%;margin-top:5px;border:1px solid #c8d6e2;border-radius:9px;padding:12px;font:inherit}textarea{min-height:160px;resize:vertical}button,a{display:inline-block;border:0;border-radius:9px;padding:12px 15px;background:var(--t);color:#fff;text-decoration:none;font-weight:bold;cursor:pointer;margin-top:15px}.back{background:#e9f1f6;color:var(--n)}.flash{padding:13px;border-radius:9px;margin-top:17px}.success{background:#e4f8ee;color:#126443}.error{background:#fff0f0;color:#a12626}table{width:100%;border-collapse:collapse;margin-top:13px}th,td{padding:11px;text-align:left;border-bottom:1px solid #e7edf2;font-size:13px}th{background:#eff5f8;color:var(--n)}</style></head><body><main class="wrap"><section class="hero"><small>PRIVATE ALUMNI CHANNEL</small><h1>Share a concern.</h1><p>Send feedback, a concern, or a school-improvement idea privately to AYISEC Alumni administration. It will not appear in the public site or Alumni chat.</p><a class="back" href="alumni-community.php">← Back to community</a></section><?php if($message!==''){?><div class="flash <?php echo alumni_safe($tone);?>"><?php echo alumni_safe($message);?></div><?php }?><section class="card"><h2>Your message</h2><p class="note">Please do not post emergency or safeguarding matters here; contact the school directly in those situations.</p><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe($_SESSION['alumni_concern_csrf']);?>"><label>Topic<select name="category"><option>General feedback</option><option>Student welfare</option><option>School facilities</option><option>Academic standards</option><option>Alumni engagement</option><option>Other concern</option></select></label><label>Subject<input name="subject" maxlength="180" required></label><label>Message<textarea name="messagebody" maxlength="5000" required></textarea></label><button name="submit_concern">Send private concern</button></form></section><section class="card"><h2>My submitted concerns</h2><?php if($history&&mysqli_num_rows($history)>0){?><table><thead><tr><th>Topic</th><th>Subject</th><th>Status</th><th>Date</th></tr></thead><tbody><?php while($row=mysqli_fetch_assoc($history)){?><tr><td><?php echo alumni_safe($row['category']);?></td><td><?php echo alumni_safe($row['subject']);?></td><td><?php echo alumni_safe(ucfirst($row['status']));?></td><td><?php echo alumni_safe(date('d M Y',strtotime($row['createdat'])));?></td></tr><?php }?></tbody></table><?php }else{?><p class="note">You have not submitted a concern yet.</p><?php }?></section></main></body></html>
